// Fails when app components use raw colors or arbitrary values instead of design tokens, or when
// any component hides the focus outline (DESIGN.md). src/components/ui is generated by the shadcn
// CLI and only edited to apply the tokens, so only the focus rule applies there.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const generated = join("src", "components", "ui");
const appRules = [
  { name: "raw color", pattern: /#[0-9a-fA-F]{3,8}\b|\b(?:rgb|rgba|hsl|hsla|oklch|oklab)\(/g },
  // An arbitrary value such as w-[13px]; an arbitrary variant such as data-[side=bottom]: is fine.
  { name: "arbitrary value", pattern: /\b[\w:-]+-\[[^\]]+\](?!:)/g },
];
const allRules = [
  // The 2 px focus outline in index.css is the only focus indicator, and it survives contrast themes.
  { name: "hidden focus outline", pattern: /\boutline-(?:none|hidden)\b|\bring-ring\//g },
];

function* files(dir) {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) yield* files(path);
    else if (/\.tsx?$/.test(name) && !/\.test\.tsx?$/.test(name)) yield path;
  }
}

const problems = [];
for (const file of files("src")) {
  const rules = file.startsWith(generated) ? allRules : [...appRules, ...allRules];
  readFileSync(file, "utf8")
    .split("\n")
    .forEach((line, index) => {
      for (const { name, pattern } of rules) {
        for (const match of line.matchAll(pattern)) {
          problems.push(`${relative(".", file)}:${index + 1}  ${name}: ${match[0]}`);
        }
      }
    });
}

if (problems.length > 0) {
  console.error(
    `Use design tokens and keep the focus outline (see DESIGN.md):\n${problems.join("\n")}`,
  );
  process.exit(1);
}
console.log("Design tokens: no raw colors, arbitrary values, or hidden focus outlines.");
